      </DialogTrigger>

      <DialogContent className="max-h-[calc(100dvh-2rem)] overflow-y-auto sm:max-w-md">
        <form onSubmit={handleSubmit} noValidate className="grid gap-5">
          <DialogHeader>
            <DialogTitle>Share your feedback</DialogTitle>
            <DialogDescription>
              Tell us how Northwind is working for you. Every message is read by
              our product team.
            </DialogDescription>
          </DialogHeader>

          <div className="grid gap-2">
            <Label id={ratingLabelId}>How would you rate your experience?</Label>
            <ToggleGroup
              type="single"
              variant="outline"
              spacing={2}
              value={rating}
              onValueChange={(value) => {
                // Radix allows deselecting; keep the current rating instead.
                if (!value) return;
                setRating(value);
                setShowError(false);
              }}
              aria-labelledby={ratingLabelId}
              aria-describedby={showError ? errorId : undefined}
              aria-invalid={showError || undefined}
              disabled={submitting}
              className="w-full flex-wrap"
            >
              {RATINGS.map(({ value, label, icon: Icon }) => (
                <ToggleGroupItem
                  key={value}
                  value={value}
                  aria-label={`${value} out of 5, ${label}`}
                  className="h-auto flex-1 flex-col gap-1 px-2 py-2 text-xs data-[state=on]:border-primary data-[state=on]:bg-primary/10 data-[state=on]:text-foreground"
                >
                  <Icon className="size-5" aria-hidden="true" />
                  {label}
                </ToggleGroupItem>
              ))}
            </ToggleGroup>
            {showError ? (
              <p
                id={errorId}
                role="alert"
                className="text-sm text-destructive"
              >
                Please choose a rating before sending.
              </p>
            ) : null}
          </div>

          <div className="grid gap-2">
            <Label htmlFor={messageId}>
              Anything you&apos;d like to add?{" "}
              <span className="font-normal text-muted-foreground">
                (optional)
              </span>
            </Label>
            <Textarea
              id={messageId}
              value={message}
              onChange={(e) => setMessage(e.target.value.slice(0, MAX_LENGTH))}
              maxLength={MAX_LENGTH}
              rows={4}
              disabled={submitting}
              placeholder="What worked well? What could be better?"
              aria-describedby={messageHelpId}
              className="max-h-48 resize-none"
            />
            <p
              id={messageHelpId}
              className="text-right text-xs text-muted-foreground"
            >
              {message.length}/{MAX_LENGTH}
            </p>
          </div>

          <DialogFooter>
            <DialogClose asChild>
              <Button type="button" variant="outline" disabled={submitting}>
                Cancel
              </Button>
            </DialogClose>
            <Button type="submit" disabled={submitting}>
              {submitting ? "Sending…" : "Send feedback"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

